-- C -> B: each website reports its OWN ledger totals to the central ledger (once a day and after every payment change), so the owner report can put A, B and C side by side.
-- One row per website and period (YYYY-MM); sending the same period again replaces it, never adds a second row.
CREATE TABLE IF NOT EXISTS site_summary (site TEXT NOT NULL, period_key TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'INR', paid_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, revenue_minor INTEGER NOT NULL DEFAULT 0, fee_minor INTEGER NOT NULL DEFAULT 0, tax_minor INTEGER NOT NULL DEFAULT 0, refunded_minor INTEGER NOT NULL DEFAULT 0, commission_accrued_minor INTEGER NOT NULL DEFAULT 0, commission_paid_minor INTEGER NOT NULL DEFAULT 0, reported_ms INTEGER NOT NULL, PRIMARY KEY (site, period_key, currency));
CREATE TABLE IF NOT EXISTS report_log (id INTEGER PRIMARY KEY AUTOINCREMENT, made_ms INTEGER NOT NULL, kind TEXT NOT NULL, emailed INTEGER NOT NULL DEFAULT 0, email_status TEXT, bytes INTEGER);
